styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  align-items: end;
  column-gap: var(--g-gap);
  position: relative;
  height: calc(var(--vh, 1vh) * 80);
  padding-bottom: calc(var(--vh, 1vh) * 80);
}
section[data-skill-hub] .-w .note {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: var(--h0);
  background-color: var(--c-black);
}
section[data-skill-hub] .-w p {
  grid-column-start: 3;
  grid-column-end: 13;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: calc(var(--h1) * 2);
  padding-left: 10%;
  padding-right: 10%;
}
section[data-skill-hub] .-w .image-1 {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  overflow: hidden;
  transform: translateZ(0);
  clip-path: polygon(
    max(calc(var(--lerp) * 0.25%), 0%) max(calc(var(--lerp) * 0.25%), 0%),
    min(calc(100% - var(--lerp) * -0.25%), 100%) max(calc(var(--lerp) * -0.25%), 0%),
    min(calc(100% - var(--lerp) * 0.25%), 100%) min(calc(100% - var(--lerp) * 0.25%), 100%),
    max(calc(var(--lerp) * -0.25%), 0%) min(calc(100% - var(--lerp) * -0.25%), 100%)
  );
}
section[data-skill-hub] .-w .image-1 img {
  scale: calc(1 + min((var(--lerp) * var(--lerp) * 0.0001), 1));
}
section[data-skill-hub] .-w .title {
  grid-column-start: 3;
  grid-column-end: 15;
  grid-row-start: 1;
  align-self: end;
  position: relative;
  margin-bottom: calc(var(--vh, 1vh) * 5);
}

@media (min-width: 1024px) {
  section[data-skill-hub] .-w {
    min-height: 1024px;
    height: min(calc(var(--vh, 1vh) * 80), calc(var(--vw, 1lvw) * 80));
  }
  section[data-skill-hub] .-w p {
    grid-column-start: 6;
    grid-column-end: 10;
  }
  section[data-skill-hub] .-w .image-1 {
    grid-column-start: 5;
    grid-column-end: 11;
  }
  section[data-skill-hub] .-w .title {
    grid-column-start: 3;
  }
}
@media (min-width: 1920px) {
  section[data-skill-hub] .-w .image-1 {
    grid-column-start: 6;
    grid-column-end: 10;
  }
  section[data-skill-hub] .-w .title {
    grid-column-start: 5;
  }
}
